#' Estimate Cohen's f-Squared
#' and Generate the Corresponding Sampling Distribution
#' Using the Nonparametric Bootstrap
#'
#' @author Ivan Jacob Agaloos Pesigan
#'
#' @details Cohen's \eqn{f^2} for the whole model,
#'   \eqn{f^2 = R^2 / (1 - R^2)},
#'   and the local \eqn{f^2} of each regressor,
#'   \eqn{f^2_j = sr^2_j / (1 - R^2)},
#'   where \eqn{sr_j} is the semipartial correlation,
#'   are derived from each bootstrap sample.
#'   Confidence intervals are generated by obtaining
#'   percentiles corresponding to \eqn{100(1 - \alpha)\%}
#'   from the generated sampling distribution,
#'   where \eqn{\alpha} is the significance level.
#'
#' @return Returns an object
#'   of class `betanb` which is a list with the following elements:
#'   \describe{
#'     \item{call}{Function call.}
#'     \item{args}{Function arguments.}
#'     \item{thetahatstar}{Sampling distribution of
#'       \eqn{f^2} (column `fsq`) and the local \eqn{f^2}
#'       (one column per regressor).}
#'     \item{jackknife}{Jackknife estimates.}
#'     \item{vcov}{Sampling variance-covariance matrix.}
#'     \item{est}{Vector of estimates.}
#'     \item{fun}{Function used ("FSqNB").}
#'   }
#'
#' @inheritParams BetaNB
#'
#' @references
#' Selya, A. S., Rose, J. S., Dierker, L. C., Hedeker, D., & Mermelstein,
#' R. J. (2012).
#' A practical guide to calculating Cohen's f2,
#' a measure of local effect size, from PROC MIXED.
#' *Frontiers in Psychology*, *3*, 111.
#' \doi{10.3389/fpsyg.2012.00111}
#'
#' @examples
#' # Data ---------------------------------------------------------------------
#' data("nas1982", package = "betaNB")
#'
#' # Fit Model in lm ----------------------------------------------------------
#' object <- lm(QUALITY ~ NARTIC + PCTGRT + PCTSUPP, data = nas1982)
#'
#' # NB -----------------------------------------------------------------------
#' nb <- NB(
#'   object,
#'   R = 100, # use a large value e.g., 5000L for actual research
#'   seed = 0508
#' )
#'
#' # FSqNB --------------------------------------------------------------------
#' out <- FSqNB(nb, alpha = 0.05)
#'
#' ## Methods -----------------------------------------------------------------
#' print(out)
#' summary(out)
#' coef(out)
#' vcov(out)
#' confint(out, level = 0.95)
#'
#' @family Beta Nonparametric Bootstrap Functions
#' @keywords betaNB fsq
#' @export
FSqNB <- function(object,
                  alpha = c(0.05, 0.01, 0.001)) {
  stopifnot(
    inherits(
      x = object,
      what = "nb"
    )
  )
  xnames <- object$lm_process$xnames
  fun <- "FSqNB"
  est <- .FSqLM(object$lm_process)
  spcor <- object$es$spcor
  spcor_jack <- object$es_jackknife$spcor
  colnames(spcor) <- colnames(spcor_jack) <- xnames
  thetahatstar <- .FSq(
    rsq = object$es$rsq[, 1],
    spcor = spcor
  )
  jackknife <- .FSq(
    rsq = object$es_jackknife$rsq[, 1],
    spcor = spcor_jack
  )
  vcov <- stats::var(thetahatstar)
  colnames(vcov) <- rownames(vcov) <- names(est)
  out <- list(
    call = match.call(),
    args = list(
      object = object,
      alpha = alpha
    ),
    thetahatstar = thetahatstar,
    jackknife = jackknife,
    vcov = vcov,
    est = est,
    fun = fun
  )
  class(out) <- c(
    "betanb",
    class(out)
  )
  out
}
